// AddVariety handles add variety requests.
func (h *CropHandler) AddVariety(ctx context.Context, req *connect.Request[pb.AddVarietyRequest]) (*connect.Response[pb.AddVarietyResponse], error) {
	if req.Msg.GetCropId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "crop_id is required")
	}
	if req.Msg.GetName() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "name is required")
	}
	tenantID := tenantIDOrContext(ctx, req.Msg.GetTenantId())

	// Resolve crop UUID to internal ID for the variety FK.
	crop, err := h.svc.GetCrop(ctx, req.Msg.GetCropId())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}

	variety := &domain.CropVariety{
		CropID:                     crop.ID,
		TenantID:                   tenantID,
		Name:                       strings.TrimSpace(req.Msg.GetName()),
		Description:                req.Msg.GetDescription(),
		MaturityDays:               req.Msg.GetMaturityDays(),
		YieldPotentialKgPerHectare: req.Msg.GetYieldPotentialKgPerHectare(),
		IsHybrid:                   req.Msg.GetIsHybrid(),
		DiseaseResistance:          req.Msg.GetDiseaseResistance(),
		SuitableRegions:            req.Msg.GetSuitableRegions(),
		SeedRateKgPerHectare:       req.Msg.GetSeedRateKgPerHectare(),
	}

	created, err := h.svc.AddVariety(ctx, variety)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	proto := cropVarietyToProto(created)
	proto.CropId = req.Msg.GetCropId()
	return connect.NewResponse(&pb.AddVarietyResponse{Variety: proto}), nil
}

// ListVarieties handles list varieties requests.
func (h *CropHandler) ListVarieties(ctx context.Context, req *connect.Request[pb.ListVarietiesRequest]) (*connect.Response[pb.ListVarietiesResponse], error) {
	if req.Msg.GetCropId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "crop_id is required")
	}
	tenantID := tenantIDOrContext(ctx, req.Msg.GetTenantId())

	varieties, total, err := h.svc.ListVarieties(ctx, req.Msg.GetCropId(), tenantID, req.Msg.GetPageSize(), req.Msg.GetPageOffset())
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	result := make([]*pb.CropVariety, len(varieties))
	for i, v := range varieties {
		p := cropVarietyToProto(v)
		p.CropId = req.Msg.GetCropId()
		result[i] = p
	}
	return connect.NewResponse(&pb.ListVarietiesResponse{
		Varieties:  result,
		TotalCount: total,
	}), nil
}

