// GenerateRecommendation handles recommendation generation requests.
func (h *CropHandler) GenerateRecommendation(ctx context.Context, req *connect.Request[pb.GenerateRecommendationRequest]) (*connect.Response[pb.GenerateRecommendationResponse], error) {
	if req.Msg.GetCropId() == "" {
		return nil, errors.BadRequest("INVALID_ARGUMENT", "crop_id is required")
	}
	tenantID := tenantIDOrContext(ctx, req.Msg.GetTenantId())

	input := &domain.RecommendationInput{
		CropID:              req.Msg.GetCropId(),
		TenantID:            tenantID,
		RecommendationType:  req.Msg.GetRecommendationType(),
		CurrentGrowthStage:  req.Msg.GetCurrentGrowthStage(),
		CurrentTemperature:  req.Msg.GetCurrentTemperature(),
		CurrentHumidity:     req.Msg.GetCurrentHumidity(),
		CurrentSoilPH:       req.Msg.GetCurrentSoilPh(),
		CurrentSoilMoisture: req.Msg.GetCurrentSoilMoisture(),
	}

	rec, err := h.svc.GenerateRecommendation(ctx, input)
	if err != nil {
		return nil, errors.ToConnectError(err)
	}
	proto := cropRecommendationToProto(rec)
	if proto != nil {
		proto.CropId = req.Msg.GetCropId()
	}
	return connect.NewResponse(&pb.GenerateRecommendationResponse{
		Recommendation: proto,
	}), nil
}

// ---------- helpers ----------

func tenantIDOrContext(ctx context.Context, tenantID string) string {
	if tenantID != "" {
		return tenantID
	}
	return p9context.TenantID(ctx)
}

func categoryToProto(c domain.CropCategory) pb.CropCategory {
	switch c {
	case domain.CropCategoryCereal:
		return pb.CropCategory_CROP_CATEGORY_CEREAL
	case domain.CropCategoryLegume:
		return pb.CropCategory_CROP_CATEGORY_LEGUME
	case domain.CropCategoryVegetable:
		return pb.CropCategory_CROP_CATEGORY_VEGETABLE
	case domain.CropCategoryFruit:
		return pb.CropCategory_CROP_CATEGORY_FRUIT
	case domain.CropCategoryOilseed:
		return pb.CropCategory_CROP_CATEGORY_OILSEED
	case domain.CropCategoryFiber:
		return pb.CropCategory_CROP_CATEGORY_FIBER
	case domain.CropCategorySpice:
		return pb.CropCategory_CROP_CATEGORY_SPICE
	default:
		return pb.CropCategory_CROP_CATEGORY_UNSPECIFIED
	}
}

func categoryFromProto(c pb.CropCategory) domain.CropCategory {
	switch c {
	case pb.CropCategory_CROP_CATEGORY_CEREAL:
		return domain.CropCategoryCereal
	case pb.CropCategory_CROP_CATEGORY_LEGUME:
		return domain.CropCategoryLegume
	case pb.CropCategory_CROP_CATEGORY_VEGETABLE:
		return domain.CropCategoryVegetable
	case pb.CropCategory_CROP_CATEGORY_FRUIT:
		return domain.CropCategoryFruit
	case pb.CropCategory_CROP_CATEGORY_OILSEED:
		return domain.CropCategoryOilseed
	case pb.CropCategory_CROP_CATEGORY_FIBER:
		return domain.CropCategoryFiber
	case pb.CropCategory_CROP_CATEGORY_SPICE:
		return domain.CropCategorySpice
	default:
		return domain.CropCategoryUnspecified
	}
}

func cropToProto(c *domain.Crop) *pb.Crop {
	if c == nil {
		return nil
	}

	crop := &pb.Crop{
		Id:                      c.ID,
		TenantId:                c.TenantID,
		Name:                    c.Name,
		ScientificName:          c.ScientificName,
		Family:                  c.Family,
		Category:                categoryToProto(c.Category),
		Description:             c.Description,
		ImageUrl:                c.ImageURL,
		DiseaseSusceptibilities: c.DiseaseSusceptibilities,
		CompanionPlants:         c.CompanionPlants,
		RotationGroup:           c.RotationGroup,
		Version:                 int32(c.Version),
		CreatedAt:               timestamppb.New(c.CreatedAt),
	}

	if c.UpdatedAt != nil {
		crop.UpdatedAt = timestamppb.New(*c.UpdatedAt)
	}

	if len(c.Varieties) > 0 {
		crop.Varieties = make([]*pb.CropVariety, len(c.Varieties))
		for i := range c.Varieties {
			crop.Varieties[i] = cropVarietyToProto(&c.Varieties[i])
		}
	}

	if len(c.GrowthStages) > 0 {
		crop.GrowthStages = make([]*pb.GrowthStage, len(c.GrowthStages))
		for i := range c.GrowthStages {
			crop.GrowthStages[i] = growthStageToProto(&c.GrowthStages[i])
		}
	}

	if c.Requirements != nil {
		crop.Requirements = cropRequirementsToProto(c.Requirements)
	}

	return crop
}

func cropVarietyToProto(v *domain.CropVariety) *pb.CropVariety {
	if v == nil {
		return nil
	}

	variety := &pb.CropVariety{
		Id:                         v.ID,
		Name:                       v.Name,
		Description:                v.Description,
		MaturityDays:               v.MaturityDays,
		YieldPotentialKgPerHectare: v.YieldPotentialKgPerHectare,
		IsHybrid:                   v.IsHybrid,
		DiseaseResistance:          v.DiseaseResistance,
		SuitableRegions:            v.SuitableRegions,
		SeedRateKgPerHectare:       v.SeedRateKgPerHectare,
		CreatedAt:                  timestamppb.New(v.CreatedAt),
	}

	if v.UpdatedAt != nil {
		variety.UpdatedAt = timestamppb.New(*v.UpdatedAt)
	}

	return variety
}

func growthStageToProto(gs *domain.CropGrowthStage) *pb.GrowthStage {
	if gs == nil {
		return nil
	}

	stage := &pb.GrowthStage{
		Id:                   gs.ID,
		Name:                 gs.Name,
		StageOrder:           gs.StageOrder,
		DurationDays:         gs.DurationDays,
		WaterRequirementMm:   gs.WaterRequirementMM,
		NutrientRequirements: gs.NutrientRequirements,
		Description:          gs.Description,
		OptimalTempMin:       gs.OptimalTempMin,
		OptimalTempMax:       gs.OptimalTempMax,
		CreatedAt:            timestamppb.New(gs.CreatedAt),
	}

	if gs.UpdatedAt != nil {
		stage.UpdatedAt = timestamppb.New(*gs.UpdatedAt)
	}

	return stage
}

func cropRequirementsToProto(r *domain.CropRequirements) *pb.CropRequirements {
	if r == nil {
		return nil
	}

	req := &pb.CropRequirements{
		Id:                       r.ID,
		OptimalTempMin:           r.OptimalTempMin,
		OptimalTempMax:           r.OptimalTempMax,
		OptimalHumidityMin:       r.OptimalHumidityMin,
		OptimalHumidityMax:       r.OptimalHumidityMax,
		OptimalSoilPhMin:         r.OptimalSoilPhMin,
		OptimalSoilPhMax:         r.OptimalSoilPhMax,
		WaterRequirementMmPerDay: r.WaterRequirementMMPerDay,
		SunlightHours:            r.SunlightHours,
		FrostTolerant:            r.FrostTolerant,
		DroughtTolerant:          r.DroughtTolerant,
		SoilTypePreference:       r.SoilTypePreference,
		NutrientRequirements:     r.NutrientRequirements,
		CreatedAt:                timestamppb.New(r.CreatedAt),
	}

	if r.UpdatedAt != nil {
		req.UpdatedAt = timestamppb.New(*r.UpdatedAt)
	}

	return req
}

func cropRecommendationToProto(r *domain.CropRecommendation) *pb.CropRecommendation {
	if r == nil {
		return nil
	}

	rec := &pb.CropRecommendation{
		Id:                    r.ID,
		TenantId:              r.TenantID,
		RecommendationType:    r.RecommendationType,
		Title:                 r.Title,
		Description:           r.Description,
		Severity:              r.Severity,
		ConfidenceScore:       r.ConfidenceScore,
		Parameters:            r.Parameters,
		ApplicableGrowthStage: r.ApplicableGrowthStage,
		CreatedAt:             timestamppb.New(r.CreatedAt),
	}

	if r.ValidFrom != nil {
		rec.ValidFrom = timestamppb.New(*r.ValidFrom)
	}
	if r.ValidUntil != nil {
		rec.ValidUntil = timestamppb.New(*r.ValidUntil)
	}

	return rec
}
